let raw = $json.body !== undefined ? $json.body : $json;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = $json; } }
const src = raw.body && typeof raw.body === 'object' ? { ...raw, ...raw.body } : raw;
return [{ json: {
  event_type: src.event_type || 'unknown',
  user_id: String(src.user_id || ''),
  name: src.name || '',
  phone: String(src.phone || '').replace(/\s/g,''),
  email: src.email || '',
  session_id: src.session_id || ('sess_' + Date.now()),
  movie_id: src.movie_id || null,
  movie_title: src.movie_title || null,
  genre: src.genre || null,
  price_kes: src.price_kes || null,
  failure_reason: src.failure_reason || null,
  channel_pref: src.channel_pref || 'sms',
  ts: src.ts || new Date().toISOString()
}}];

const atUsername = String($env.AT_USERNAME || '').trim();
const atApiKey = String($env.AT_API_KEY || '').trim();
const atSenderId = String($env.AT_SENDER_ID || '').trim();
if (!atUsername || !atApiKey || !atSenderId) {
  throw new Error("Africa's Talking SMS requires AT_USERNAME, AT_API_KEY, and AT_SENDER_ID on the n8n container");
}
const ev = $('Normalize Upsell Input').first().json;
let ai;
try { ai = JSON.parse($json.choices?.[0]?.message?.content || $json.message?.content || $json.text || '{}'); }
catch(e) { ai = { message: 'Loved that ending? Grab a hand-picked bundle at 20% off — tonight only.', bundle_titles: 'Nairobi Nights + Sauti ya Mtaa', bundle_price: 'KES 215' }; }
const storefront = (typeof $env !== 'undefined' && $env.STOREFRONT_URL ? $env.STOREFRONT_URL : 'https://yakwetu.dontire.com').replace(/\/$/, '');
const link = `${storefront}/?bundle=1&u=${encodeURIComponent(ev.user_id)}`;
const msg = (ai.message || 'More stories for you on Yakwetu').trim();
const full_message = `${msg}\n\n🎬 ${ai.bundle_titles || 'Bundle'} (${ai.bundle_price || ''})\nGrab it: ${link}`;
return [{ json: {
  ...ev,
  bundle_titles: ai.bundle_titles || 'Nairobi Nights + Sauti ya Mtaa',
  bundle_price: ai.bundle_price || 'KES 215',
  offer_link: link,
  full_message
}}];
